SET local check_function_bodies = off;

CREATE TABLE "public"."inventory_batches" (
  "batch_id"           bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "product_id"         bigint                   NOT NULL,
  "supplier_id"        bigint,
  "storage_id"         bigint                   NOT NULL,
  "batch_code"         character varying(50)    NOT NULL,
  "quantity_remaining" numeric(12,3)            NOT NULL DEFAULT 0,
  "expiry_date"        date                     NOT NULL,
  "received_at"        timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "inventory_batches_pkey" PRIMARY KEY (batch_id),
  CONSTRAINT "inventory_batches_quantity_remaining_check" CHECK ((quantity_remaining >= (0)::numeric))
);

ALTER TABLE "public"."inventory_batches"
  ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON TABLE "public"."inventory_batches" FROM "anon";

CREATE TABLE "public"."products" (
  "product_id"      bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "product_code"    character varying(30)    NOT NULL,
  "product_name"    character varying(100)   NOT NULL,
  "category"        character varying(50)    NOT NULL,
  "unit"            character varying(20)    NOT NULL,
  "min_stock_level" numeric(12,3)            NOT NULL DEFAULT 0,
  "is_active"       boolean                  NOT NULL DEFAULT true,
  "created_at"      timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "products_min_stock_level_check" CHECK ((min_stock_level >= (0)::numeric)),
  CONSTRAINT "products_pkey" PRIMARY KEY (product_id),
  CONSTRAINT "products_product_code_key" UNIQUE (product_code)
);

ALTER TABLE "public"."products"
  ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON TABLE "public"."products" FROM "anon";

CREATE TABLE "public"."reports" (
  "report_id"    bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "report_name"  character varying(150)   NOT NULL,
  "report_type"  text                     NOT NULL,
  "start_date"   date,
  "end_date"     date,
  "file_format"  text                     NOT NULL,
  "generated_by" uuid                     NOT NULL,
  "generated_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "chk_report_dates" CHECK ((((start_date IS NULL) AND (end_date IS NULL)) OR ((start_date IS NOT NULL) AND (end_date IS NOT NULL) AND (start_date <= end_date)))),
  CONSTRAINT "reports_file_format_check" CHECK ((file_format = ANY (ARRAY['PDF'::text, 'CSV'::text]))),
  CONSTRAINT "reports_pkey" PRIMARY KEY (report_id),
  CONSTRAINT "reports_report_type_check" CHECK ((report_type = ANY (ARRAY['INVENTORY'::text, 'STOCK_MOVEMENT'::text, 'EXPIRY'::text, 'SUPPLIER'::text, 'TEMPERATURE'::text])))
);

ALTER TABLE "public"."reports"
  ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON TABLE "public"."reports" FROM "anon";

CREATE TABLE "public"."stock_transactions" (
  "movement_id"      bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "batch_id"         bigint                   NOT NULL,
  "user_id"          uuid                     NOT NULL,
  "transaction_type" text                     NOT NULL,
  "reason"           text                     NOT NULL,
  "quantity"         numeric(12,3)            NOT NULL,
  "reference_code"   character varying(50),
  "notes"            character varying(255),
  "recorded_at"      timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "stock_transactions_pkey" PRIMARY KEY (movement_id),
  CONSTRAINT "stock_transactions_quantity_check" CHECK ((quantity > (0)::numeric)),
  CONSTRAINT "stock_transactions_reason_check" CHECK ((reason = ANY (ARRAY['RECEIPT'::text, 'SALE'::text, 'TRANSFER'::text, 'ADJUSTMENT'::text, 'WASTE'::text, 'RETURN'::text]))),
  CONSTRAINT "stock_transactions_transaction_type_check" CHECK ((transaction_type = ANY (ARRAY['IN'::text, 'OUT'::text])))
);

ALTER TABLE "public"."stock_transactions"
  ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON TABLE "public"."stock_transactions" FROM "anon";

CREATE TABLE "public"."storage_areas" (
  "storage_id"      bigint                 GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "storage_name"    character varying(100) NOT NULL,
  "min_temperature" numeric(5,2)           NOT NULL,
  "max_temperature" numeric(5,2)           NOT NULL,
  "is_active"       boolean                NOT NULL DEFAULT true,
  CONSTRAINT "chk_temperature_limits" CHECK ((min_temperature < max_temperature)),
  CONSTRAINT "storage_areas_pkey" PRIMARY KEY (storage_id),
  CONSTRAINT "storage_areas_storage_name_key" UNIQUE (storage_name)
);

ALTER TABLE "public"."storage_areas"
  ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON TABLE "public"."storage_areas" FROM "anon";

CREATE TABLE "public"."suppliers" (
  "supplier_id"    bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "supplier_name"  character varying(100)   NOT NULL,
  "contact_person" character varying(100),
  "phone"          character varying(20),
  "email"          character varying(100),
  "address"        text,
  "is_active"      boolean                  NOT NULL DEFAULT true,
  "created_at"     timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "suppliers_pkey" PRIMARY KEY (supplier_id)
);

ALTER TABLE "public"."suppliers"
  ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON TABLE "public"."suppliers" FROM "anon";

CREATE TABLE "public"."system_alerts" (
  "alert_id"           bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "product_id"         bigint,
  "batch_id"           bigint,
  "storage_id"         bigint,
  "temperature_log_id" bigint,
  "alert_type"         text                     NOT NULL,
  "title"              character varying(100)   NOT NULL,
  "message"            text                     NOT NULL,
  "status"             text                     NOT NULL DEFAULT 'OPEN'::text,
  "acknowledged_at"    timestamp with time zone,
  "resolved_at"        timestamp with time zone,
  "created_at"         timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "chk_alert_acknowledgement" CHECK (((status <> 'ACKNOWLEDGED'::text) OR (acknowledged_at IS NOT NULL))),
  CONSTRAINT "chk_alert_resolution" CHECK (((status <> 'RESOLVED'::text) OR (resolved_at IS NOT NULL))),
  CONSTRAINT "chk_alert_target" CHECK ((((alert_type = 'LOW_STOCK'::text) AND (product_id IS
    NOT NULL) AND (batch_id IS NULL) AND (storage_id IS NULL) AND (temperature_log_id IS NULL)) OR
    ((alert_type = ANY (ARRAY['NEAR_EXPIRY'::text, 'EXPIRED'::text])) AND (batch_id IS
    NOT NULL) AND (product_id IS NULL) AND (storage_id IS NULL) AND (temperature_log_id IS NULL)) OR ((alert_type = 'TEMP_OUT_OF_RANGE'::text) AND (temperature_log_id IS
    NOT NULL) AND (product_id IS NULL) AND (batch_id IS NULL) AND (storage_id IS NULL)) OR ((alert_type = 'SENSOR_OFFLINE'::text) AND (storage_id IS
    NOT NULL) AND (product_id IS NULL) AND (batch_id IS NULL) AND (temperature_log_id IS NULL)))),
  CONSTRAINT "system_alerts_alert_type_check"
    CHECK ((alert_type = ANY (ARRAY['LOW_STOCK'::text, 'NEAR_EXPIRY'::text, 'EXPIRED'::text, 'TEMP_OUT_OF_RANGE'::text, 'SENSOR_OFFLINE'::text]))),
  CONSTRAINT "system_alerts_pkey" PRIMARY KEY (alert_id),
  CONSTRAINT "system_alerts_status_check" CHECK ((status = ANY (ARRAY['OPEN'::text, 'ACKNOWLEDGED'::text, 'RESOLVED'::text]))),
  CONSTRAINT "system_alerts_temperature_log_id_key" UNIQUE (temperature_log_id)
);

ALTER TABLE "public"."system_alerts"
  ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON TABLE "public"."system_alerts" FROM "anon";

CREATE TABLE "public"."temperature_logs" (
  "log_id"               bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "storage_id"           bigint                   NOT NULL,
  "reading_key"          character varying(80)    NOT NULL,
  "temperature"          numeric(5,2)             NOT NULL,
  "min_limit_at_reading" numeric(5,2)             NOT NULL,
  "max_limit_at_reading" numeric(5,2)             NOT NULL,
  "recorded_at"          timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "chk_logged_limits" CHECK ((min_limit_at_reading < max_limit_at_reading)),
  CONSTRAINT "temperature_logs_pkey" PRIMARY KEY (log_id),
  CONSTRAINT "temperature_logs_reading_key_key" UNIQUE (reading_key)
);

ALTER TABLE "public"."temperature_logs"
  ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON TABLE "public"."temperature_logs" FROM "anon";

CREATE TABLE "public"."users" (
  "user_id"    uuid                     NOT NULL,
  "username"   character varying(50)    NOT NULL,
  "full_name"  character varying(100)   NOT NULL,
  "role"       text                     NOT NULL,
  "status"     text                     NOT NULL DEFAULT 'ACTIVE'::text,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "users_pkey" PRIMARY KEY (user_id),
  CONSTRAINT "users_role_check" CHECK ((role = ANY (ARRAY['ADMIN'::text, 'STAFF'::text]))),
  CONSTRAINT "users_status_check" CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'INACTIVE'::text]))),
  CONSTRAINT "users_username_key" UNIQUE (username)
);

ALTER TABLE "public"."users"
  ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON TABLE "public"."users" FROM "anon";

CREATE OR REPLACE FUNCTION public.ingest_temperature (
  p_storage_id  bigint,
  p_reading_key text,
  p_temperature numeric
)
  RETURNS TABLE (
    saved_log_id       bigint,
    temperature_status text,
    alert_created      boolean,
    is_duplicate       boolean
  )
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
DECLARE
    v_min NUMERIC(5,2);
    v_max NUMERIC(5,2);
    v_temp NUMERIC(5,2);
    v_log_id BIGINT;
    v_abnormal BOOLEAN;
BEGIN
    -- Validate reading identifier
    IF p_reading_key IS NULL OR
       p_reading_key !~ '^[A-Za-z0-9_-]{1,80}$'
    THEN
        RAISE EXCEPTION 'Invalid reading key';
    END IF;

    -- Validate temperature
    IF p_temperature IS NULL OR
       p_temperature < -55 OR
       p_temperature > 125
    THEN
        RAISE EXCEPTION 'Invalid temperature';
    END IF;

    -- Retrieve storage limits
    SELECT
        s.min_temperature,
        s.max_temperature
    INTO v_min, v_max
    FROM public.storage_areas s
    WHERE s.storage_id = p_storage_id
      AND s.is_active = TRUE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Storage area not found';
    END IF;

    v_temp := ROUND(p_temperature, 2);

    -- Insert temperature reading
    INSERT INTO public.temperature_logs (
        storage_id,
        reading_key,
        temperature,
        min_limit_at_reading,
        max_limit_at_reading
    )
    VALUES (
        p_storage_id,
        p_reading_key,
        v_temp,
        v_min,
        v_max
    )
    ON CONFLICT (reading_key) DO NOTHING
    RETURNING log_id INTO v_log_id;

    -- Ignore duplicate readings
    IF v_log_id IS NULL THEN
        RETURN QUERY
        SELECT
            NULL::BIGINT,
            'DUPLICATE'::TEXT,
            FALSE,
            TRUE;
        RETURN;
    END IF;

    -- Evaluate temperature
    v_abnormal := v_temp < v_min OR v_temp > v_max;

    -- Generate alert if abnormal
    IF v_abnormal THEN
        INSERT INTO public.system_alerts (
            temperature_log_id,
            alert_type,
            title,
            message
        )
        VALUES (
            v_log_id,
            'TEMP_OUT_OF_RANGE',
            'Abnormal Cold Storage Temperature',
            FORMAT(
                'Temperature %s C is outside the range %s C to %s C',
                v_temp, v_min, v_max
            )
        );
    END IF;

    RETURN QUERY
    SELECT
        v_log_id,
        CASE WHEN v_abnormal
            THEN 'ABNORMAL'
            ELSE 'NORMAL'
        END::TEXT,
        v_abnormal,
        FALSE;
END;
$function$;

REVOKE ALL ON FUNCTION "public"."ingest_temperature"(bigint, text, numeric) FROM PUBLIC, "anon", "authenticated";

