CREATE INDEX idx_alert_batch ON public.system_alerts USING btree (batch_id);

CREATE INDEX idx_alert_storage ON public.system_alerts USING btree (storage_id);

CREATE INDEX idx_alert_type_status ON public.system_alerts USING btree (alert_type, status);

CREATE INDEX idx_batch_product_expiry ON public.inventory_batches USING btree (product_id, expiry_date);

CREATE INDEX idx_batch_storage ON public.inventory_batches USING btree (storage_id);

CREATE INDEX idx_batch_supplier ON public.inventory_batches USING btree (supplier_id);

CREATE INDEX idx_reports_type_date ON public.reports USING btree (report_type, generated_at DESC);

CREATE INDEX idx_reports_user ON public.reports USING btree (generated_by);

CREATE INDEX idx_stock_batch_date ON public.stock_transactions USING btree (batch_id, recorded_at DESC);

CREATE INDEX idx_stock_user ON public.stock_transactions USING btree (user_id);

CREATE INDEX idx_temperature_storage_date ON public.temperature_logs USING btree (storage_id, recorded_at DESC);

CREATE POLICY "Active users read batches" ON "public"."inventory_batches"
  FOR SELECT
  TO "authenticated"
  USING ((EXISTS ( SELECT 1
   FROM public.users u
  WHERE ((u.user_id = ( SELECT auth.uid() AS uid)) AND (u.status = 'ACTIVE'::text)))));

CREATE POLICY "Active users read products" ON "public"."products"
  FOR SELECT
  TO "authenticated"
  USING ((EXISTS ( SELECT 1
   FROM public.users u
  WHERE ((u.user_id = ( SELECT auth.uid() AS uid)) AND (u.status = 'ACTIVE'::text)))));

CREATE POLICY "Admins read reports" ON "public"."reports"
  FOR SELECT
  TO "authenticated"
  USING ((EXISTS ( SELECT 1
   FROM public.users u
  WHERE ((u.user_id = ( SELECT auth.uid() AS uid)) AND (u.role = 'ADMIN'::text) AND (u.status = 'ACTIVE'::text)))));

CREATE POLICY "Active users read transactions" ON "public"."stock_transactions"
  FOR SELECT
  TO "authenticated"
  USING ((EXISTS ( SELECT 1
   FROM public.users u
  WHERE ((u.user_id = ( SELECT auth.uid() AS uid)) AND (u.status = 'ACTIVE'::text)))));

CREATE POLICY "Active users read storage" ON "public"."storage_areas"
  FOR SELECT
  TO "authenticated"
  USING ((EXISTS ( SELECT 1
   FROM public.users u
  WHERE ((u.user_id = ( SELECT auth.uid() AS uid)) AND (u.status = 'ACTIVE'::text)))));

CREATE POLICY "Active users read suppliers" ON "public"."suppliers"
  FOR SELECT
  TO "authenticated"
  USING ((EXISTS ( SELECT 1
   FROM public.users u
  WHERE ((u.user_id = ( SELECT auth.uid() AS uid)) AND (u.status = 'ACTIVE'::text)))));

CREATE POLICY "Active users read alerts" ON "public"."system_alerts"
  FOR SELECT
  TO "authenticated"
  USING ((EXISTS ( SELECT 1
   FROM public.users u
  WHERE ((u.user_id = ( SELECT auth.uid() AS uid)) AND (u.status = 'ACTIVE'::text)))));

CREATE POLICY "Active users read temperatures" ON "public"."temperature_logs"
  FOR SELECT
  TO "authenticated"
  USING ((EXISTS ( SELECT 1
   FROM public.users u
  WHERE ((u.user_id = ( SELECT auth.uid() AS uid)) AND (u.status = 'ACTIVE'::text)))));

CREATE POLICY "Read own profile" ON "public"."users"
  FOR SELECT
  TO "authenticated"
  USING ((user_id = ( SELECT auth.uid() AS uid)));

